def transform(grid):
    h, w = len(grid), len(grid[0])
    bg = max(set(v for row in grid for v in row),
             key=lambda v: sum(row.count(v) for row in grid))

    # Separate the connected pattern from the isolated points.
    remaining = {(r, c) for r in range(h) for c in range(w)
                 if grid[r][c] != bg}
    components = []
    while remaining:
        start = remaining.pop()
        comp = {start}
        stack = [start]
        while stack:
            r, c = stack.pop()
            for p in ((r-1,c), (r+1,c), (r,c-1), (r,c+1)):
                if p in remaining:
                    remaining.remove(p)
                    comp.add(p)
                    stack.append(p)
        components.append(comp)

    pattern = max(components, key=len)
    markers = [p for comp in components if comp is not pattern for p in comp]
    ar, ac = next((r, c) for r, c in pattern if grid[r][c] == 5)
    offsets = [(r-ar, c-ac, grid[r][c]) for r, c in pattern]

    out = [row[:] for row in grid]
    for r, c in markers:
        for dr, dc, color in offsets:
            rr, cc = r + dr, c + dc
            if 0 <= rr < h and 0 <= cc < w:
                out[rr][cc] = color
    return out
